package odc;
import java.util.*;
public final class TaskEngineTest {
    static long checks;static void check(boolean x,String m){checks++;if(!x)throw new AssertionError(m);}
    static TaskEngine.Node node(int i,int rack,int cpu,int ram,int disk,int net,int psu,int... gpu){return new TaskEngine.Node(new UUID(0,i+1),rack,cpu,ram,disk,net,psu,12,20,Arrays.copyOf(gpu,4));}
    static TaskEngine.Task task(int id,int type,int c,int g,int ram,int disk,int net){TaskEngine.Task t=new TaskEngine.Task(id,type);t.enabled=true;t.cpu=c;t.gpus=g;t.ram=ram;t.disk=disk;t.net=net;return t;}
    static TaskEngine.Plan plan(List<TaskEngine.Node> ns,List<TaskEngine.Task> ts,int[] cap,int wan){return TaskEngine.plan(ns,ts,cap,wan,Collections.emptyMap(),Collections.emptySet());}
    static void named(){List<TaskEngine.Node> ns=Arrays.asList(node(0,0,160,64,512,1000,500,2,2),node(1,0,40,16,512,100,250,1));
        TaskEngine.Task a=task(1,TaskEngine.BANK,50,0,4,8,16),b=task(2,TaskEngine.AI,0,1,8,32,32),m=task(3,1,0,1,4,1,4);TaskEngine.Plan p=plan(ns,Arrays.asList(a,b,m),new int[]{1000},1000);
        check(p.tasks.get(1).full&&p.tasks.get(2).full&&p.tasks.get(3).full,"mixed same server");check(p.cpu[0]==60,"GPU overhead separately reserved");check(Integer.bitCount(p.gpu[0])==2,"exclusive cards");check(p.disk[0]==41,"disk reserve");check(p.ram[0]==16,"RAM reserve");
        TaskEngine.Task strict=task(1,TaskEngine.AI,0,3,8,32,32);strict.strict=true;TaskEngine.Plan q=plan(ns,Arrays.asList(strict,m),new int[]{1000},1000);check(q.tasks.get(1).work==0&&q.tasks.get(1).slices.isEmpty(),"strict rollback");check(q.tasks.get(3).full,"released GPU");
        TaskEngine.Task ai=task(4,TaskEngine.AI,0,1,8,32,32);TaskEngine.Plan low=plan(Collections.singletonList(node(0,0,160,64,512,100,500,1)),Collections.singletonList(ai),new int[]{100},100);check(low.tasks.get(4).work==0,"VRAM per card");
        TaskEngine.Plan partial=plan(ns,Collections.singletonList(ai),new int[]{16},16);check(partial.tasks.get(4).work==160&&!partial.tasks.get(4).full,"flex WAN throttle");check(partial.actualGPU[0][0]==50,"dynamic GPU load");check(partial.power[0]<p.power[0],"power dynamic");
        ai.auto=false;ai.manual.put(ns.get(0).id,new TaskEngine.Limit(0,2));TaskEngine.Plan man=plan(ns,Collections.singletonList(ai),new int[]{100},100);check(man.gpu[0]==2,"manual physical GPU");ai.manual.get(ns.get(0).id).ram=4;check(plan(ns,Collections.singletonList(ai),new int[]{100},100).tasks.get(4).work==0,"manual RAM cap");ai.manual.get(ns.get(0).id).ram=64;ai.manual.get(ns.get(0).id).net=4;check(plan(ns,Collections.singletonList(ai),new int[]{100},100).tasks.get(4).net==4,"manual network cap");
        List<TaskEngine.Node> weak=Collections.singletonList(node(0,0,160,64,512,100,50,2));TaskEngine.Task t=task(1,1,0,1,4,1,4);check(plan(weak,Collections.singletonList(t),new int[]{100},100).overload.contains(0),"PSU trips");check(TaskEngine.plan(weak,Collections.singletonList(t),new int[]{100},100,Collections.emptyMap(),Collections.singleton(0)).tasks.get(1).work==0,"excluded server no reward");
        Map<UUID,Integer> groups=new HashMap<>();groups.put(ns.get(1).id,2);TaskEngine.Task bank=task(1,3,50,0,4,8,16);bank.group=2;check(TaskEngine.plan(ns,Collections.singletonList(bank),new int[]{100},100,groups,Collections.emptySet()).cpu[0]==0,"group filter");
        TaskEngine.Task disabled=task(1,0,100,0,4,1,4);disabled.enabled=false;check(plan(ns,Collections.singletonList(disabled),new int[]{100},100).tasks.get(1).work==0,"disabled job");
    }
    public static void main(String[] args){named();Random random=new Random(20261125L);int cases=15000;for(int it=0;it<cases;it++){int n=1+random.nextInt(12),r=1+random.nextInt(4),wan=random.nextInt(300),j=1+random.nextInt(10);int[] caps=new int[r];for(int i=0;i<r;i++)caps[i]=random.nextInt(250);List<TaskEngine.Node> ns=new ArrayList<>();List<TaskEngine.Task> ts=new ArrayList<>();Set<Integer> excluded=new HashSet<>();Map<UUID,Integer> groups=new HashMap<>();for(int i=0;i<n;i++){TaskEngine.Node x=node(i,random.nextInt(r),random.nextBoolean()?40:160,4*(1+random.nextInt(16)),64*(1+random.nextInt(8)),random.nextInt(101),random.nextInt(300)+20,random.nextInt(5),random.nextInt(5),random.nextInt(5),random.nextInt(5));ns.add(x);groups.put(x.id,random.nextInt(4));if(random.nextInt(10)==0)excluded.add(i);}
        for(int i=0;i<j;i++){int type=random.nextInt(6);TaskEngine.Task t=task(i+1,type,type>=4?0:random.nextInt(201),type==3?0:random.nextInt(7),2+random.nextInt(65),1+random.nextInt(64),1+random.nextInt(150));t.enabled=random.nextInt(5)!=0;t.strict=random.nextBoolean();t.priority=1+random.nextInt(10);t.group=random.nextInt(4);t.auto=random.nextBoolean();if(!t.auto)for(TaskEngine.Node x:ns)if(random.nextBoolean()){TaskEngine.Limit l=new TaskEngine.Limit(random.nextInt(101),random.nextInt(16));l.ram=1+random.nextInt(64);l.net=random.nextInt(101);t.manual.put(x.id,l);}ts.add(t);}
        TaskEngine.Plan p=TaskEngine.plan(ns,ts,caps,wan,groups,excluded);int total=0;int[] sw=new int[r],cpu=new int[n],mask=new int[n],ram=new int[n],disk=new int[n],net=new int[n];for(TaskEngine.Task t:ts){TaskEngine.Result x=p.tasks.get(t.id);check(x!=null,"result");if(!t.enabled||t.strict&&!x.full)check(x.work==0&&x.slices.isEmpty(),"rollback/disabled");for(TaskEngine.Slice s:x.slices){TaskEngine.Node v=ns.get(s.node);check(!excluded.contains(s.node),"excluded");check((mask[s.node]&s.mask)==0,"GPU double allocation");check(s.work>0&&s.net>0&&s.ram>0&&s.disk>0,"positive allocation");if(t.group>0)check(groups.get(v.id)==t.group,"group");if(!t.auto){TaskEngine.Limit l=t.manual.get(v.id);check(l!=null,"manual membership");check((s.mask&~l.mask)==0&&s.ram<=l.ram&&s.net<=l.net,"manual caps");}for(int k=0;k<4;k++)if((s.mask&(1<<k))!=0)check(v.gpu[k]>0&&TaskEngine.vram(v.gpu[k])>=TaskEngine.minVram(t.type),"VRAM");cpu[s.node]+=s.cpu;mask[s.node]|=s.mask;ram[s.node]+=s.ram;disk[s.node]+=s.disk;net[s.node]+=s.net;}}
        for(int i=0;i<n;i++){TaskEngine.Node v=ns.get(i);check(cpu[i]==p.cpu[i]&&mask[i]==p.gpu[i]&&ram[i]==p.ram[i]&&disk[i]==p.disk[i]&&net[i]==p.net[i],"totals");check(cpu[i]<=100&&ram[i]<=v.ram&&disk[i]<=v.disk&&net[i]<=v.net,"node capacity");check(p.actualCPU[i]<=p.cpu[i],"actual CPU");for(int k=0;k<4;k++)check(p.actualGPU[i][k]>=0&&p.actualGPU[i][k]<=100,"GPU load");check(excluded.contains(i)?p.power[i]==0:p.overload.contains(i)==(p.power[i]>v.psu),"PSU");total+=net[i];sw[v.rack]+=net[i];}check(total<=wan,"WAN");for(int i=0;i<r;i++)check(sw[i]<=caps[i],"switch cap");}
        System.out.println("PASS TaskEngine: "+cases+" randomized scenarios, "+checks+" assertions plus targeted scenarios");}
}
